package io.github.turbopro.ism.bootstrap;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;
import org.springframework.http.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class TenantCreationIT extends SiteInitializationSupport {
    record Plan(long id,long published,long draft,long offline,String code){}
    Plan plan(){long id=900000+IDS.incrementAndGet()*10L;String code="CREATE_"+id;jdbc.update("INSERT INTO plt_package(id,package_code,package_name,status) VALUES(?,?,?,'ACTIVE')",id,code,"创建套餐"+id);for(int i=1;i<=3;i++)jdbc.update("INSERT INTO plt_package_version(id,package_id,version_no,version_name,status) VALUES(?,?,?,'版本',?)",id+i,id,i,i==1?"PUBLISHED":i==2?"DRAFT":"OFFLINE");return new Plan(id,id+1,id+2,id+3,code);}
    Map<String,Object> createBody(Plan p,String code){return new HashMap<>(Map.of("code",code,"name","创建验收企业","timezone","Asia/Shanghai","locale","zh-CN","packageVersionId",Long.toString(p.published())));}
    ResponseEntity<JsonNode> request(String method,String path,String token,String key,Object body){var h=new HttpHeaders();h.setBearerAuth(token);if(key!=null)h.set("Idempotency-Key",key);return http.exchange(path,HttpMethod.valueOf(method),new HttpEntity<>(body,h),JsonNode.class);}
    ResponseEntity<JsonNode> create(String token,String key,Map<String,Object> body){return request("POST","/api/console/tenants",token,key,body);}
    JsonNode ok(ResponseEntity<JsonNode> r){assertThat(r.getStatusCode()).withFailMessage("%s",r.getBody()).isEqualTo(HttpStatus.OK);return r.getBody().path("data");}
    String creator(){consoleUsers();if(jdbc.queryForObject("SELECT COUNT(*) FROM plt_user WHERE id=790003",Integer.class)==0){jdbc.update("INSERT INTO plt_role(id,role_code,role_name,status) VALUES(790003,'CREATE_ONLY','仅创建','ACTIVE')");jdbc.update("INSERT INTO plt_role_permission(role_id,permission_id) SELECT 790003,id FROM plt_permission WHERE permission_code='platform:tenant:create'");jdbc.update("INSERT INTO plt_user(id,username,display_name,password_hash,status,force_password_change) VALUES(790003,'create-only','创建专员',?,'ACTIVE',0)",passwords.encode("Console#Pass123"));jdbc.update("INSERT INTO plt_user_role(user_id,role_id) VALUES(790003,790003)");}return http.postForEntity("/api/console/auth/login",Map.of("username","create-only","password","Console#Pass123","deviceId","creation-tests"),JsonNode.class).getBody().path("data").path("accessToken").asText();}
    @Test void minimalOptionsNeedCreateRatherThanFullPackagePermission(){var p=plan();String t=creator();assertThat(request("GET","/api/console/tenants/package-options?page=2147483647",t,null,null).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);var data=ok(request("GET","/api/console/tenants/package-options?q="+p.code()+"&size=1",t,null,null));assertThat(data.path("total").asInt()).isOne();var option=data.path("items").get(0);assertThat(option.path("id").asText()).isEqualTo(Long.toString(p.published()));assertThat(option.has("modules")).isFalse();assertThat(option.has("quotaJson")).isFalse();assertThat(ok(request("GET","/api/console/tenants/package-options?q="+p.code()+"&size=1&page=1",t,null,null)).path("items").isEmpty()).isTrue();assertThat(ok(request("GET","/api/console/tenants/package-options?q=%25",t,null,null)).path("total").asInt()).isZero();assertThat(request("GET","/api/console/packages",t,null,null).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(request("GET","/api/console/tenants/package-options",login(false),null,null).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);}
    @Test void unavailableAndInvalidInputsNeverAllocateTenants(){var p=plan();String t=login(true);int before=jdbc.queryForObject("SELECT COUNT(*) FROM plt_tenant",Integer.class);for(long version:new long[]{p.draft(),p.offline(),Long.MAX_VALUE}){var b=createBody(p,"INVALID-"+version);b.put("packageVersionId",Long.toString(version));assertThat(create(t,"version-"+version,b).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);}for(var field:Map.of("timezone","not a zone","locale","zh_CN","packageVersionId","abc").entrySet()){var b=createBody(p,"INVALID-FIELD");b.put(field.getKey(),field.getValue());assertThat(create(t,"field-"+field.getKey(),b).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);}jdbc.update("UPDATE plt_package SET status='DISABLED' WHERE id=?",p.id());assertThat(ok(request("GET","/api/console/tenants/package-options?q="+p.code(),t,null,null)).path("total").asInt()).isZero();assertThat(create(t,"disabled-parent",createBody(p,"DISABLED-PARENT")).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM plt_tenant",Integer.class)).isEqualTo(before);}
    @Test void successfulReplayRetainsOneTenantSubscriptionAndAudit(){var p=plan();String t=login(true),key="create-"+p.id();var b=createBody(p,"REPLAY-"+p.id());var first=ok(create(t,key,b));assertThat(first.path("status").asText()).isEqualTo("PROVISIONING");assertThat(first.path("initializationStatus").asText()).isEqualTo("PENDING");jdbc.update("UPDATE plt_package_version SET status='OFFLINE' WHERE id=?",p.published());assertThat(ok(create(t,key,b))).isEqualTo(first);var changed=new HashMap<>(b);changed.put("name","另一个请求");assertThat(create(t,key,changed).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);long id=first.path("id").asLong();assertThat(count("plt_subscription",id)).isOne();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sys_audit_event WHERE action='TENANT_CREATE' AND object_id=?",Integer.class,id)).isOne();}
    @Test void concurrentReplayAndDuplicateCodesHaveSingleDurableResult()throws Exception{var p=plan();String t=login(true);var pool=Executors.newFixedThreadPool(2);try{for(boolean sameKey:new boolean[]{true,false}){String code=(sameKey?"SAME-":"DUP-")+p.id();var b=createBody(p,code);var gate=new CountDownLatch(1);var one=pool.submit(()->{gate.await();return create(t,"race-a-"+code,b);});var two=pool.submit(()->{gate.await();return create(t,(sameKey?"race-a-":"race-b-")+code,b);});gate.countDown();var a=one.get(30,TimeUnit.SECONDS);var c=two.get(30,TimeUnit.SECONDS);if(sameKey){assertThat(a.getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(c.getBody().path("data")).isEqualTo(a.getBody().path("data"));}else assertThat(List.of(a.getStatusCode(),c.getStatusCode())).containsExactlyInAnyOrder(HttpStatus.OK,HttpStatus.CONFLICT);long id=jdbc.queryForObject("SELECT id FROM plt_tenant WHERE tenant_code=?",Long.class,code);assertThat(count("plt_subscription",id)).isOne();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sys_audit_event WHERE action='TENANT_CREATE' AND object_id=?",Integer.class,id)).isOne();}}finally{pool.shutdownNow();}}
    @Test void auditFailureRollsBackCreationAndRetryUsesOriginalKey()throws Exception{var p=plan();String t=login(true),key="rollback-"+p.id(),code="ROLLBACK-"+p.id();var b=createBody(p,code);trigger("CREATE TRIGGER tenant_creation_audit_failure BEFORE INSERT ON sys_audit_event FOR EACH ROW BEGIN IF NEW.action='TENANT_CREATE' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic audit failure'; END IF; END");try{assertThat(create(t,key,b).getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM plt_tenant WHERE tenant_code=?",Integer.class,code)).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sys_idempotency_record WHERE operation_code='TENANT_CREATE' AND idempotency_key=?",Integer.class,key)).isZero();}finally{trigger("DROP TRIGGER tenant_creation_audit_failure");}assertThat(ok(create(t,key,b)).path("code").asText()).isEqualTo(code);}
    @Test void creationInitializationAndMandatoryPasswordChangeCloseTheOpeningFlow(){var p=plan();String console=login(true);for(String mode:List.of("SINGLE_SITE","MULTI_SITE")){String code=mode+"-"+p.id();long id=ok(create(console,code,createBody(p,code))).path("id").asLong();assertThat(count("iam_user",id)).isZero();ok(initialize(id,console,"initialize-"+code,body(mode)));assertStructure(id,mode.equals("SINGLE_SITE"));var credentials=Map.of("tenantCode",code,"username","site-admin","password","Site#Initial123","deviceId","opening");var login=ok(http.postForEntity("/api/auth/login",credentials,JsonNode.class));assertThat(login.path("user").path("passwordChangeRequired").asBoolean()).isTrue();String access=login.path("accessToken").asText();assertThat(request("GET","/api/organizations/tree",access,null,null).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);ok(request("POST","/api/auth/change-password",access,null,Map.of("oldPassword","Site#Initial123","newPassword","Changed#Pass1234")));var fresh=new HashMap<>(credentials);fresh.put("password","Changed#Pass1234");String changed=ok(http.postForEntity("/api/auth/login",fresh,JsonNode.class)).path("accessToken").asText();assertThat(request("GET","/api/organizations/tree",changed,null,null).getStatusCode()).isEqualTo(HttpStatus.OK);}}
    @Test void revokedCreationPermissionAlsoBlocksReceiptReplay(){var p=plan();String t=creator();var b=createBody(p,"REVOKE-"+p.id());String key="revoke-"+p.id();ok(create(t,key,b));jdbc.update("DELETE rp FROM plt_role_permission rp JOIN plt_permission p ON p.id=rp.permission_id WHERE rp.role_id=790003 AND p.permission_code='platform:tenant:create'");try{assertThat(create(t,key,b).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(request("GET","/api/console/tenants/package-options",t,null,null).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);}finally{jdbc.update("INSERT INTO plt_role_permission(role_id,permission_id) SELECT 790003,id FROM plt_permission WHERE permission_code='platform:tenant:create'");}}
    void trigger(String sql)throws Exception{try(var c=java.sql.DriverManager.getConnection(MYSQL.getJdbcUrl(),"root",MYSQL.getPassword());var s=c.createStatement()){s.execute(sql);}}
}
